#!/bin/sh

set -eux pipefail

cd "$(dirname "$0")/../.."

. ./scripts/local/gaiad_binary.sh
. ./scripts/local/wasm_checksum.sh

CHAIN_ID="test-ibc-eth"
KEYRING="test"

# Store Wasm code
echo '{
 "messages": [
  {
   "@type": "/ibc.lightclients.wasm.v1.MsgStoreCode",
   "signer": "cosmos10d07y265gmmuvt4z0w9aw880jnsr700j6zn9kn",
   "wasm_byte_code": ""
  }
 ],
 "title": "eth-light-client",
 "deposit": "10000000stake",
 "summary": "cw-ics08-wasm ethereum light client",
 "expedited": false
}' > proposal.json

# Multi-node layout (matches run_cosmos_node_n.sh):
#   homes : $GAIA_BASE/val<i>     (default GAIA_BASE=$HOME/.gaia-multi)
#   keys  : val<i>                (i in [0, NUM_NODES))
#   rpc   : tcp://127.0.0.1:$((RPC_BASE + i))
NUM_NODES="${NUM_NODES:-20}"
GAIA_BASE="${GAIA_BASE:-$HOME/.gaia-multi}"
RPC_BASE="${RPC_BASE:-31000}"
PRIMARY_NODE="tcp://127.0.0.1:${RPC_BASE}"

"$GAIAD" tx gov submit-proposal proposal.json \
  --from val0 \
  --home "$GAIA_BASE/val0" \
  --node "$PRIMARY_NODE" \
  --chain-id "$CHAIN_ID" \
  --keyring-backend "$KEYRING" \
  --gas 200000000 \
  --gas-prices 1stake \
  -y

# `tx gov submit-proposal -y` is async; poll until the proposal is indexed
# instead of relying on a fixed sleep that races on slow boxes.
PROPOSAL_ID=""
for attempt in $(seq 1 30); do
  PROPOSAL_ID=$(
    "$GAIAD" q gov proposals --node "$PRIMARY_NODE" -o json 2>/dev/null \
      | jq -r '.proposals // [] | sort_by(.id | tonumber) | last | .id // empty'
  )
  if [ -n "$PROPOSAL_ID" ]; then
    break
  fi
  echo "Waiting for proposal to be indexed (attempt $attempt/30)..."
  sleep 2
done

if [ -z "$PROPOSAL_ID" ]; then
  echo "ERROR: no proposal indexed after 60s — check submit-proposal output above" >&2
  exit 1
fi
echo "Proposal ID: $PROPOSAL_ID"

# Vote yes from every validator so we cross the 2/3 quorum regardless of stake
# distribution. Each vote goes through that validator's own RPC to spread load.
i=0
while [ "$i" -lt "$NUM_NODES" ]; do
  NODE_RPC="tcp://127.0.0.1:$((RPC_BASE + i))"
  "$GAIAD" tx gov vote "$PROPOSAL_ID" yes \
    --from "val$i" \
    --home "$GAIA_BASE/val$i" \
    --node "$NODE_RPC" \
    --chain-id "$CHAIN_ID" \
    --keyring-backend "$KEYRING" \
    --gas-prices 1stake \
    -y
  i=$((i + 1))
done

# Poll proposal status + checksum instead of a fixed sleep. The proposal
# only executes after voting_period expires (set in genesis); 30s is often
# too short on a fresh chain.
CHECKSUM=$(wasm_checksum_from_proposal proposal.json)
STORED_CHECKSUM=""
for attempt in $(seq 1 60); do
  status=$("$GAIAD" q gov proposal "$PROPOSAL_ID" --node "$PRIMARY_NODE" -o json 2>/dev/null \
    | jq -r '.proposal.status // .status // "UNKNOWN"')
  if wasm_checksum_is_stored "$CHECKSUM" --node "$PRIMARY_NODE" 2>/dev/null; then
    STORED_CHECKSUM=$CHECKSUM
    break
  fi
  echo "Proposal status=$status, computed checksum not yet stored (attempt $attempt/60)..."
  sleep 5
done

if [ -z "$STORED_CHECKSUM" ]; then
  echo "ERROR: computed wasm checksum $CHECKSUM was never stored. Last proposal status: $status" >&2
  echo "       Check '$GAIAD q gov proposal $PROPOSAL_ID' for tally + execution details." >&2
  exit 1
fi

echo "Checksum: 0x$CHECKSUM"
